import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  texture, uv, vec2, vec3, mix, smoothstep, dot, clamp, abs, positionLocal, uniform, float
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DataTexture, DirectionalLight, SRGBColorSpace } = ctx.THREE;

  const root = new Group();
  const disposables = [];
  const primHandles = [];
  const timelines = [];

  // ---------------------------------------------------------------
  // Placeholder textures (swapped on async load)
  // ---------------------------------------------------------------
  const makePlaceholder = (r, g, b) => {
    const t = new DataTexture(new Uint8Array([r, g, b, 255]), 1, 1);
    t.needsUpdate = true;
    return t;
  };
  const imgPlaceholder = makePlaceholder(22, 22, 29);
  const depthPlaceholder = makePlaceholder(128, 128, 128);
  disposables.push(imgPlaceholder, depthPlaceholder);

  const imgNode = texture(imgPlaceholder);
  const depthNode = texture(depthPlaceholder);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      imgNode.value = tex;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthNode.value = tex;
    });
  }

  // ---------------------------------------------------------------
  // Backdrop stage plane (7 x 6 @ z=-2.5) — surface -> background grade
  // ---------------------------------------------------------------
  const bgTop = vec3(0.086, 0.086, 0.114);   // #16161d surface
  const bgBottom = vec3(0.043, 0.043, 0.063); // #0b0b10 background
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(bgBottom, bgTop, smoothstep(0.0, 1.0, uv().y).mul(0.85).add(0.05));
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // Hero parallax plate — 4.0 x 2.5, 64x64 segments, depth displacement 0.18
  // Filmic grade: lifted blacks #0d0d12, shouldered highlights -> #e8ecf2,
  // +12% midtone contrast, -8% desat with red channel preserved, depth rim,
  // bottom scrim #0b0b1000 -> #0b0b10eb.
  // ---------------------------------------------------------------
  const plateOpacity = uniform(0);

  const plateMat = new MeshBasicNodeMaterial();
  plateMat.transparent = true;

  const raw = imgNode.rgb;
  const luma = dot(raw, vec3(0.2126, 0.7152, 0.0722));
  // -8% desaturation, red channel preserved (accent stays pure)
  const desat = mix(vec3(luma, luma, luma), raw, 0.92);
  const redSafe = vec3(raw.r, desat.g, desat.b);
  // +12% midtone contrast
  const contrasted = redSafe.sub(0.5).mul(1.12).add(0.5);
  // blacks lifted to #0d0d12
  const lift = vec3(0.051, 0.051, 0.071);
  const lifted = lift.add(contrasted.mul(vec3(1.0, 1.0, 1.0).sub(lift)));
  // highlights shouldered toward paper #e8ecf2
  const paper = vec3(0.910, 0.925, 0.949);
  const shouldered = mix(lifted, paper, smoothstep(0.72, 1.0, luma).mul(0.32));

  // silhouette rim from depth-map edges (~0.02 unit rim)
  const du = float(0.006);
  const d0 = depthNode.r;
  const dRight = texture(depthPlaceholder, uv().add(vec2(du, 0.0)));
  dRight.value = depthNode.value;
  const dUp = texture(depthPlaceholder, uv().add(vec2(0.0, du)));
  dUp.value = depthNode.value;
  // keep offset samples pointed at the loaded depth texture
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      dRight.value = tex;
      dUp.value = tex;
    });
  }
  const edge = abs(d0.sub(dRight.r)).add(abs(d0.sub(dUp.r)));
  const rim = smoothstep(0.06, 0.28, edge).mul(0.35);
  const withRim = clamp(shouldered.add(paper.mul(rim)), 0.0, 1.0);

  // bottom scrim gradient seats the caption block
  const scrimCol = vec3(0.043, 0.043, 0.063);
  const scrimA = smoothstep(0.55, 0.0, uv().y).mul(0.92);
  plateMat.colorNode = mix(withRim, scrimCol, scrimA);
  plateMat.opacityNode = plateOpacity;

  // depth displacement, amplitude 0.18 scene units
  plateMat.positionNode = positionLocal.add(vec3(0.0, 0.0, 1.0).mul(depthNode.r.mul(0.18)));

  const plateGeo = new PlaneGeometry(4.0, 2.5, 64, 64);
  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0.35, 0);
  root.add(plate);
  disposables.push(plateGeo, plateMat);

  // ---------------------------------------------------------------
  // Node-local rim light (accent hue, <= 1.5)
  // ---------------------------------------------------------------
  const rimLight = new DirectionalLight(0xff2a38, 0.9);
  rimLight.position.set(-3, 1.5, -1.5);
  root.add(rimLight);

  // ---------------------------------------------------------------
  // Caption block — bottom-left, 0.5-unit padding, 0.25 baseline rhythm
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textFor = (role, fallback) => {
    const it = items.find((i) => i.role === role);
    return typeof it?.text === 'string' ? it.text : fallback;
  };

  const captionGroup = new Group();
  captionGroup.position.set(-1.5, -0.9, 0.25);

  const kicker = ctx.fontAtlas.createText(textFor('kicker', 'NOVA ATELIER / GENEVA'), {
    fontSize: 18, color: '#ff2a38', align: 'left', letterSpacingPx: 2.2
  });
  kicker.position.set(0, 1.02, 0);
  captionGroup.add(kicker);

  const headline = ctx.fontAtlas.createText(textFor('headline', 'Time, Machined.'), {
    fontSize: 68, color: '#e8ecf2', align: 'left'
  });
  headline.position.set(0, 0.66, 0);
  captionGroup.add(headline);

  // accent hairline bar 0.75w x 0.02h, emissive 1.8
  const barMat = new MeshBasicNodeMaterial();
  barMat.colorNode = vec3(1.0, 0.165, 0.22).mul(1.8);
  const barGeo = new BoxGeometry(0.75, 0.02, 0.02);
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(0.375, 0.42, 0);
  captionGroup.add(bar);
  disposables.push(barGeo, barMat);

  const body = ctx.fontAtlas.createText(
    textFor('body', 'Every case begins as a single billet of 904L steel.'),
    { fontSize: 26, color: '#e8ecf2', align: 'left', maxWidthPx: 620 }
  );
  body.position.set(0, 0.2, 0);
  captionGroup.add(body);

  const caption = ctx.fontAtlas.createText(
    textFor('caption', 'CALIBRE NA-01 / 72 HOUR RESERVE'),
    { fontSize: 18, color: '#e8ecf2', align: 'left', letterSpacingPx: 2.2 }
  );
  caption.position.set(0, -0.1, 0.25); // foreground depth plane
  captionGroup.add(caption);

  root.add(captionGroup);

  // ---------------------------------------------------------------
  // Entrance motion: plate mount 500ms, caption rise-in +0.4 -> 0 @ 700ms +120ms
  // ---------------------------------------------------------------
  const captionTargetY = captionGroup.position.y;
  captionGroup.position.y = captionTargetY - 0.4;
  captionGroup.visible = true;

  const tl = gsap.timeline();
  tl.to(plateOpacity, { value: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(captionGroup.position, { y: captionTargetY, duration: 0.7, ease: 'power3.out' }, 0.12);
  timelines.push(tl);

  // Idle: single slow breathing transform (<= 2%)
  const breathe = gsap.to(plate.scale, {
    x: 1.015, y: 1.015, duration: 4.5, ease: 'sine.inOut', repeat: -1, yoyo: true
  });
  timelines.push(breathe);

  // ---------------------------------------------------------------
  // Cinematic primitives from config
  // ---------------------------------------------------------------
  for (const prim of (config.cinematicPrimitives ?? [])) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const handle = fn(root, prim.params ?? {});
      if (handle) primHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // Handlers + cleanup
  // ---------------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const t of timelines) t.kill();
    for (const h of primHandles) h.cleanup?.();
    for (const d of disposables) d.dispose?.();
  };

  return root;
}
